PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'owner',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,sku TEXT UNIQUE,name TEXT NOT NULL,category TEXT,description TEXT,designer TEXT,source_url TEXT,license_name TEXT,license_status TEXT NOT NULL DEFAULT 'review_required',price_cents INTEGER NOT NULL DEFAULT 0,estimated_minutes INTEGER,estimated_filament_g REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_files(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,kind TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT,version INTEGER NOT NULL DEFAULT 1,source_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_images(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,path TEXT NOT NULL,source_url TEXT,attribution TEXT,is_primary INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,sku TEXT UNIQUE,name TEXT NOT NULL,material TEXT,color TEXT,size TEXT,price_cents INTEGER NOT NULL DEFAULT 0,estimated_minutes INTEGER,estimated_filament_g REAL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT,phone TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,quote_number TEXT UNIQUE NOT NULL,customer_id TEXT REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'draft',total_cents INTEGER NOT NULL DEFAULT 0,expires_at TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_items(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL REFERENCES quotes(id) ON DELETE CASCADE,product_id TEXT REFERENCES products(id),description TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 1,unit_price_cents INTEGER NOT NULL DEFAULT 0,material TEXT,color TEXT,estimated_minutes INTEGER,estimated_filament_g REAL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,customer_id TEXT REFERENCES customers(id),quote_id TEXT REFERENCES quotes(id),status TEXT NOT NULL DEFAULT 'new',due_at TEXT,total_cents INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS printers(id TEXT PRIMARY KEY,name TEXT NOT NULL,model TEXT,status TEXT NOT NULL DEFAULT 'idle',build_x_mm REAL,build_y_mm REAL,build_z_mm REAL,octoprint_url TEXT,api_key_ref TEXT,total_hours REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS filament_spools(id TEXT PRIMARY KEY,material TEXT NOT NULL,brand TEXT,color TEXT,initial_g REAL NOT NULL,remaining_g REAL NOT NULL,cost_cents INTEGER NOT NULL DEFAULT 0,location TEXT,lot_number TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS print_jobs(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),product_id TEXT REFERENCES products(id),printer_id TEXT REFERENCES printers(id),spool_id TEXT REFERENCES filament_spools(id),status TEXT NOT NULL DEFAULT 'queued',gcode_path TEXT,octoprint_file TEXT,estimated_minutes INTEGER,estimated_filament_g REAL,actual_minutes INTEGER,actual_filament_g REAL,started_at TEXT,completed_at TEXT,success INTEGER,learning_recorded INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY,invoice_number TEXT UNIQUE NOT NULL,order_id TEXT REFERENCES orders(id),status TEXT NOT NULL DEFAULT 'draft',total_cents INTEGER NOT NULL DEFAULT 0,paid_cents INTEGER NOT NULL DEFAULT 0,due_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT,quantity REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL DEFAULT 'each',reorder_level REAL,location TEXT,cost_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS maintenance_records(id TEXT PRIMARY KEY,printer_id TEXT NOT NULL REFERENCES printers(id) ON DELETE CASCADE,kind TEXT NOT NULL,description TEXT,printer_hours REAL,cost_cents INTEGER NOT NULL DEFAULT 0,performed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_entries(id TEXT PRIMARY KEY,entity_type TEXT,entity_id TEXT,title TEXT NOT NULL,body TEXT NOT NULL,tags TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS domain_events(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,aggregate_type TEXT,aggregate_id TEXT,payload_json TEXT NOT NULL,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,processed_at TEXT);
CREATE TABLE IF NOT EXISTS automation_rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,trigger_event TEXT NOT NULL,conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,actor TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,before_json TEXT,after_json TEXT,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON print_jobs(status);
CREATE INDEX IF NOT EXISTS idx_orders_status_due ON orders(status,due_at);
